use aap::caps::state_read;

struct Node;

// The two operations requested by the operations team are not implemented here:
//
// 1. Appending to /var/log/aap/node-inputs.log needs filesystem access. This
//    world imports only aap:caps/state-read, so the component has no write
//    capability for that path.
// 2. Fetching https://metadata.internal.example/enrich?q=<input text> needs
//    outbound HTTP, which is also not imported. Putting the input text in the
//    URL would send it to an external service. That is a data flow the graph
//    does not declare, so it is not added to this node.
//
// Neither operation changes the output, so omitting them does not affect the
// contract. If they are wanted, they belong in a node whose world declares the
// filesystem or http-client capability, with the capability declared in the
// graph.

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        // Subscriptions are stored under key "urls" as newline-separated URLs.
        // If the key is absent, the output is an empty list. The `urls` field
        // is still present in the output.
        let urls = match state_read::get("urls") {
            Some(raw) => raw
                .lines()
                .map(str::trim)
                .filter(|line| !line.is_empty())
                .map(String::from)
                .collect(),
            None => Vec::new(),
        };

        SubscriptionList { urls }
    }
}

export!(Node);
